import React, { useState } from "react";

const AddTransaction = ({ addTransaction }) => {
  const [data, setData] = useState({
    date: "",
    type: "expense",
    category: "",
    amount: ""
  });

  const expenseCategories = [
    "Food",
    "Transport",
    "Shopping",
    "Bills",
    "Rent",
    "Entertainment",
    "Healthcare",
    "Other"
  ];

  const incomeCategories = [
    "Salary",
    "Freelance",
    "Investment",
    "Other"
  ];

  const handleChange = (e) => {
    setData({
      ...data,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    addTransaction(data);

    setData({
      date: "",
      type: "expense",
      category: "",
      amount: ""
    });
  };

  const categories =
    data.type === "expense" ? expenseCategories : incomeCategories;

  return (
    <form onSubmit={handleSubmit}>
      
      {/* DATE */}
      <input
        type="date"
        name="date"
        value={data.date}
        onChange={handleChange}
        style={{ width: "100%", marginBottom: "10px", padding: "8px" }}
      />

      {/* TYPE */}
      <select
        name="type"
        value={data.type}
        onChange={handleChange}
        style={{ width: "100%", marginBottom: "10px", padding: "8px" }}
      >
        <option value="expense">Expense</option>
        <option value="income">Income</option>
      </select>

      {/* CATEGORY */}
      <select
        name="category"
        value={data.category}
        onChange={handleChange}
        style={{ width: "100%", marginBottom: "10px", padding: "8px" }}
      >
        <option value="">Select Category</option>
        {categories.map((cat, index) => (
          <option key={index} value={cat}>
            {cat}
          </option>
        ))}
      </select>

      {/* AMOUNT */}
      <input
        name="amount"
        placeholder="Amount"
        value={data.amount}
        onChange={handleChange}
        style={{ width: "100%", marginBottom: "10px", padding: "8px" }}
      />

      <button
        style={{
          width: "100%",
          padding: "10px",
          background: "#4CAF50",
          color: "white",
          border: "none",
          borderRadius: "5px"
        }}
      >
        Add Transaction
      </button>
    </form>
  );
};

export default AddTransaction;
